/** Offline recovery2 revalidation before one provider restart. Never writes or calls a host/provider. */
import { readFile } from 'node:fs/promises';
import { m78CanonicalJson as canonical } from '../packages/neuvetra-database/src/m78-validation';
import { verifyM78Continuation4ReadonlyRecovery2, type Recovery2ReviewAdmission } from '../evaluations/research-qa/m78-readonly-recovery2-corrected-review';

const ACTUAL_QA_PATH = 'evaluations/research-qa/m78-readonly-recovery2-actual-independent-result.json';
const RUNTIME = { commit: '9dd9c85fb674528a2c1dd1b0138f5a2d87ba683e', deploymentId: 'f6d77b2e-6886-429b-a4d2-4873c9199ce8', imageDigest: 'sha256:3e4c2c91591a5598a85f63b4099b1b4890588ce79ec832b21b7d284b5aa89d1b', autodeploy: false } as const;
const HISTORICAL_EVALUATOR_SHA256 = '4324a96546228070f4d16b0ed6a25cbe02d56d6412d48829d1b60e176db708c1';
const CORRECTED_EVALUATOR_SHA256 = 'c45f948482a53b9e2f2ba87c1b754bb70a6f2ced079dbf8b4d85657d7b77fa78';
const RUNNER_SHA256 = '47044480d2019e4e162a0156adf81a31d557560190747102144f0006de9fbe7d';
const paths = {
  mainText: '.superpowers/m78-hosted-continuation4.jsonl', diagnosticText: '.superpowers/m78-hosted-continuation4-diagnostics.jsonl',
  baselineResultText: 'evaluations/research-qa/m78-continuation4-baseline-independent-result.json', exerciseGateText: '.superpowers/m78-continuation4-exercise-gate.json',
  providerObservationText: 'evaluations/research-qa/m78-continuation4-failure-http-observation.json', browserObservationText: 'evaluations/research-qa/m78-continuation4-browser-http-observation.json', failureReviewText: 'evaluations/research-qa/m78-continuation4-exercise-failure-qa-result.json',
  failedRecoveryJournalText: '.superpowers/m78-continuation4-readonly-recovery.jsonl', failedRecoveryDiagnosticText: '.superpowers/m78-continuation4-readonly-recovery-diagnostics.jsonl', failedRecoveryReviewText: 'evaluations/research-qa/m78-readonly-failure-review2-result.json',
  recoveryJournalText: '.superpowers/m78-continuation4-readonly-recovery2.jsonl', recoveryDiagnosticText: '.superpowers/m78-continuation4-readonly-recovery2-diagnostics.jsonl', recoveryRawCaptureText: '.superpowers/m78-continuation4-readonly-recovery2-raw-capture.jsonl', observationText: '.superpowers/m78-continuation4-readonly-recovery2-observation.json', currentSourceGateText: '.superpowers/m78-readonly-recovery2-source-gate.json',
} as const;
const fixedEvidence = {
  rootEvaluation: '.superpowers/m78-readonly-recovery2-corrected-evaluation.json',
  journal: paths.recoveryJournalText, diagnostics: paths.recoveryDiagnosticText, rawCapture: paths.recoveryRawCaptureText, observation: paths.observationText, sourceGate: paths.currentSourceGateText,
  failedRecoveryLock: '.superpowers/m78-continuation4-readonly-recovery.jsonl.lock', recovery2Lock: '.superpowers/m78-continuation4-readonly-recovery2.jsonl.lock',
  evaluator: 'evaluations/research-qa/m78-readonly-recovery2-corrected-review.ts', runner: 'tools/staging/check-m78-continuation4-readonly-recovery2.ts',
} as const;
const sha = (value: string | Uint8Array) => new Bun.CryptoHasher('sha256').update(value).digest('hex');
const check: (value: unknown, label: string) => asserts value = (value, label) => { if (!value) throw Error('Recovery2 restart validation refused: ' + label); };
const same = (left: unknown, right: unknown) => canonical(left) === canonical(right);
const exactRuntime = (value: any) => value && value.commit === RUNTIME.commit && value.deploymentId === RUNTIME.deploymentId && value.imageDigest === RUNTIME.imageDigest && value.autodeploy === false;
type Read = (path: string) => Promise<Uint8Array>;
type Verify = typeof verifyM78Continuation4ReadonlyRecovery2;

export async function validateM78Recovery2ForRestart(actualQaPath: string, expectedSha256: string, dependencies: { read: Read; verify: Verify } = { read: path => readFile(path), verify: verifyM78Continuation4ReadonlyRecovery2 }) {
  check(actualQaPath === ACTUAL_QA_PATH && /^[a-f0-9]{64}$/.test(expectedSha256), 'actual QA argument');
  const qaBytes = await dependencies.read(actualQaPath); check(sha(qaBytes) === expectedSha256, 'actual QA pin');
  const qa = JSON.parse(Buffer.from(qaBytes).toString('utf8'));
  check(qa.status === 'm78_independent_continuation4_readonly_recovery2_passed'
    && qa.reviewerId === '/root/m78_transport_probe' && qa.materialFindingsOpen === 0
    && qa.actualRecoveryAccepted === true && qa.restartAuthorizedByThisResult === false && qa.revisitAuthorizedByThisResult === false
    && qa.applicationPostRequests === 0 && qa.allCreatedAuthSessionsClosed === true && qa.unknownAuthSessions === 0
    && exactRuntime(qa.runtime) && Number.isFinite(Date.parse(qa.completedAt)), 'actual QA status/runtime');
  const requiredEvidence = Object.entries(fixedEvidence);
  check(qa.evidence && same(Object.keys(qa.evidence).sort(), requiredEvidence.map(([key]) => key).sort()), 'exact evidence keys');
  const loaded = new Map<string, Uint8Array>();
  for (const [key, path] of requiredEvidence) {
    const pin = qa.evidence[key]; check(pin?.path === path && /^[a-f0-9]{64}$/.test(pin.sha256), 'evidence pin ' + key);
    const bytes = await dependencies.read(path); check(sha(bytes) === pin.sha256, 'evidence bytes ' + key); loaded.set(path, bytes);
  }
  check(qa.evidence.evaluator.sha256 === CORRECTED_EVALUATOR_SHA256 && qa.evidence.runner.sha256 === RUNNER_SHA256
    && qa.correctionReview?.frozenEvaluatorSha256 === HISTORICAL_EVALUATOR_SHA256
    && qa.correctionReview.correctedEvaluatorSha256 === CORRECTED_EVALUATOR_SHA256
    && qa.correctionReview.all37ActualPayloadsValidated === true && qa.correctionReview.all37UnexpectedFieldMutationsRejected === true,
  'historical, corrected evaluator and runner');
  const texts = Object.fromEntries(await Promise.all(Object.entries(paths).map(async ([key, path]) => [key, Buffer.from(await dependencies.read(path)).toString('utf8')]))) as Record<keyof typeof paths, string>;
  const rootEvaluation = JSON.parse(Buffer.from(loaded.get(fixedEvidence.rootEvaluation)!).toString('utf8'));
  check(rootEvaluation.status === qa.status && rootEvaluation.actualRecoveryAccepted === true && rootEvaluation.applicationPostRequests === 0
    && rootEvaluation.allCreatedAuthSessionsClosed === true && rootEvaluation.unknownAuthSessions === 0
    && rootEvaluation.evaluatorSha256 === CORRECTED_EVALUATOR_SHA256 && same(rootEvaluation.admission, qa.reviewAdmission), 'root evaluation');
  const admission = qa.reviewAdmission as Recovery2ReviewAdmission;
  check(admission
    && admission.journalSha256 === qa.evidence.journal.sha256 && admission.diagnosticsSha256 === qa.evidence.diagnostics.sha256
    && admission.rawCaptureSha256 === qa.evidence.rawCapture.sha256 && admission.observationSha256 === qa.evidence.observation.sha256
    && admission.currentSourceGateSha256 === qa.evidence.sourceGate.sha256
    && qa.journalSha256 === admission.journalSha256 && qa.diagnosticsSha256 === admission.diagnosticsSha256
    && qa.rawCaptureSha256 === admission.rawCaptureSha256 && qa.observationSha256 === admission.observationSha256
    && qa.currentSourceGateSha256 === admission.currentSourceGateSha256, 'review admission pins');
  const sourceGate = JSON.parse(texts.currentSourceGateText), observation = JSON.parse(texts.observationText);
  check(sourceGate.status === 'm78_continuation4_readonly_recovery2_source_admitted' && sourceGate.runtime.commit === RUNTIME.commit
    && sourceGate.runtime.deploymentId === RUNTIME.deploymentId && sourceGate.runtime.imageDigest === RUNTIME.imageDigest
    && observation.status === 'm78_continuation4_readonly_recovery2_observed' && observation.currentSourceGateSha256 === admission.currentSourceGateSha256, 'source and observation');
  check(Array.isArray(sourceGate.sourcePins) && sourceGate.sourcePins.length === 182
    && new Set(sourceGate.sourcePins.map((pin: any) => pin.path)).size === sourceGate.sourcePins.length
    && sourceGate.sourcePins.every((pin: any) => typeof pin.path === 'string' && pin.path.length > 0 && /^[a-f0-9]{64}$/.test(pin.sha256)), 'exact transitive source pins');
  const sourcePinMap = new Map(sourceGate.sourcePins.map((pin: any) => [pin.path, pin.sha256]));
  check(sourcePinMap.get('evaluations/research-qa/m78-readonly-recovery2-independent-review.ts') === HISTORICAL_EVALUATOR_SHA256 && sourcePinMap.get(fixedEvidence.runner) === RUNNER_SHA256, 'required historical evaluator and runner source pins');
  for (const pin of sourceGate.sourcePins) check(sha(await dependencies.read(pin.path)) === pin.sha256, 'transitive source changed ' + pin.path);
  const evaluated = await dependencies.verify(texts, admission);
  check(evaluated.status === qa.status && evaluated.actualRecoveryAccepted === true && evaluated.applicationPostRequests === 0
    && evaluated.allCreatedAuthSessionsClosed === true && evaluated.unknownAuthSessions === 0
    && evaluated.addedTypedRecords === 37 && evaluated.reports === 5 && evaluated.rosterArtifactReads === 24
    && evaluated.sourceUnion === 10 && evaluated.grossKgCo2eExact === '126850.17632025', 'frozen evaluator result');
  for (const [key, value] of Object.entries(evaluated)) if (key !== 'hostedCalls') check(rootEvaluation[key] === value, 'root evaluation field ' + key);
  return {
    status: 'm78_readonly_recovery2_restart_validation_passed' as const,
    actualQa: { path: actualQaPath, sha256: expectedSha256 }, reviewAdmission: admission, runtime: RUNTIME,
    completedAt: qa.completedAt, recoveryObservationSha256: admission.observationSha256, recoverySourceGateSha256: admission.currentSourceGateSha256,
    failedRecoveryLock: qa.evidence.failedRecoveryLock, recovery2Lock: qa.evidence.recovery2Lock,
  };
}

if (import.meta.main) {
  const [path, expected] = process.argv.slice(2); const result = await validateM78Recovery2ForRestart(path ?? '', expected ?? ''); console.log(JSON.stringify(result));
}

